fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Iterate through each parent index
    for i in 0..(n / 2) {
        // Check left child
        let left_index = 2 * i + 1;
        if left_index < n && a[i] > a[left_index] {
            return false; // Parent is greater than left child
        }
        
        // Check right child
        let right_index = 2 * i + 2;
        if right_index < n && a[i] > a[right_index] {
            return false; // Parent is greater than right child
        }
    }
    true // All parent-child comparisons satisfied the min-heap property
}